static atomic64_t mxfs_dlm_stat_handoff_b2c_max = ATOMIC64_INIT(0);
static atomic64_t mxfs_dlm_stat_handoff_b2c_gt50 = ATOMIC64_INIT(0);
static atomic64_t mxfs_dlm_stat_handoff_b2c_gt500 = ATOMIC64_INIT(0);
