							__be32 dm = *(__be32 *)rb;
							bool dkbf = (dm == cpu_to_be32(XFS_DIR2_BLOCK_MAGIC) ||
								     dm == cpu_to_be32(XFS_DIR3_BLOCK_MAGIC));
							int de_n = mxfs_dir3_disk_has_extra_inum(
								mp, dbp->b_addr, rb, blksz, icbf, dkbf);
