MODULE_PARM_DESC(iwr,
                 "Inode-cluster partial-write decision trace (P28-IWR*): "
                 "0=off (default), 1=ratelimited decision+reason");

/* sess25 (ccloop): xfs_iflush resurrection guard window (P25-RESURRECT-SKIP).
 * Skip flushing a stale-live in-core inode whose COHERENT on-disk copy a peer
 * FREED (di_mode=0 di_nlink=0) and is 1..N free-bumps ahead (disk_gen -
 * incore_gen in [1,N]) — preventing the dir_reuse_coherency leaf double-claim.
 * 0 disables the guard. Default 64 (covers an inode# reused a few dozen times
 * across rm-rf rounds; a chunk-init random gen lands in the window only
 * N/2^32 of the time). Runtime-tunable to characterize the chunk-reinit tail. */
int mxfs_resurrect_gen_window = 64;
module_param_named(resurrect_gen_window, mxfs_resurrect_gen_window, int, 0644);
MODULE_PARM_DESC(resurrect_gen_window,
                 "iflush resurrection guard: skip flushing a peer-freed inode "
                 "when (u32)(disk_gen - incore_gen) is in [1,N]; 0=off, default 64");

/* sess6(ccloop 12e0d157): 32-node cache_coherency shared-dir reload-storm gate. */
module_param_named(dir_slow_handoff_gate, mxfs_dir_slow_handoff_gate, int, 0644);
MODULE_PARM_DESC(dir_slow_handoff_gate,
                 "Skip the slow-path fresh-grant dir reload when there was no "
                 "genuine cross-node EX handoff since our last adopt (no peer "
                 "modified the dir -> cached image authoritative); 0=off default");

/*
 * sess17 (ccloop): gate for the dir DATA/leaf-block xfsaild-skip chokepoint
 * (the 2/tcp crash_consistency fix).  0=detector-only (P16-DIRBLK-SUBMIT logs
 * the skip-predicate state for every dir-block write, gated by dirwr/instr, but
 * no write is suppressed — instrumented instrument phase); 1=enforce (suppress an
 * NL-released or prior-tenure dir-block write at the single bio chokepoint,
 * mirroring the proven P61 bmbt guard).  Default 1 once proven.
 */
int mxfs_dirskip_enabled;	/* default 0: detect-only (enforce refuted sess17) */
module_param_named(dirskip, mxfs_dirskip_enabled, int, 0644);
MODULE_PARM_DESC(dirskip,
                 "Suppress stale xfsaild dir-block writes (NL-released only): "
                 "0=detect-only (default), 1=enforce NL-released skip");

/* sess2 (ccloop a16ec5f2) instrumented block watch — see xfs_buf_submit_bio. */
unsigned long long mxfs_watch_daddr;
module_param_named(watch_daddr, mxfs_watch_daddr, ullong, 0644);
module_param_named(read_attr_probe, mxfs_read_attr_probe, int, 0644);
MODULE_PARM_DESC(read_attr_probe,
	"sess5: attribute cold (bio-issued) reads by class at the submit chokepoint; periodic dmesg + ratelimited stack for inode-real reads. 0=off");

/*
 * sess5(ccloop 12e0d157) READ-STORM FIX (GFS2/Fable prior-owner design,
 * DEFAULT-OFF pending coherency validation): in mxfs_dlm_reload_inode, the
 * inode-cluster stale+FUA-re-read (xfs_mxfs_dlm.c ~14417) assumes "a peer wrote
 * this inode".  For a reused inode this node freed+re-allocated ITSELF (the
 * dlm_scaling private-subdir create/rm loop; any single-writer inode), NO peer
 * held the EX grant since our last handoff, so the on-disk image cannot differ
 * from in-core — the stale + cache-bypassing FUA re-read is pure waste and, at
 * 32-node concurrency, saturates the shared iSCSI target (the read storm).
 * When on, skip the reload stale iff mxfs_v5_dlm_inode_grant_handoff reports NO
 * cross-node EX handoff since our acted gen (peer-reuse still stales → coherent).
 * MUST validate cache_coherency/strong_consistency/dir_reuse @4 and @16 before
 * defaulting on. 0=off (baseline: always stale).
 */
module_param_named(reload_skip_owned, mxfs_reload_skip_owned, int, 0644);
MODULE_PARM_DESC(reload_skip_owned,
	"sess5: skip reload_inode cluster-stale+FUA-reread when no cross-node EX handoff (self-reused inode, in-core authoritative). 0=off");
MODULE_PARM_DESC(watch_daddr,
                 "Log every xfs_buf bio touching this envelope-relative daddr "
                 "(0=off): direction, content magic, ops, comm; stack on writes");
